import {extraAlphabet,extraAlphabetNotes} from './alphabet-v4.js';
import {characterSvg} from './characters.js';
import {createLocalStore,mondayWeek,currentStreak,localDay} from './local-state.js';
import {createOfflineActivities} from './offline-activities.js';
import {readingSupport} from './reading-support-v3.js';
import {alphabetSupport,alphabetNotes} from './alphabet-support.js';
import {createLearningHub} from './learning-hub.js';
import {phraseBridge,noteBridge} from './support-v3.js';
import {rankVoices,scoreSpeech} from './speech.js';
import {getUiLanguage,setUiLanguage,getTheme,toggleTheme,startLocalization,celebrate,interfaceText} from './presentation.js';
import {levels} from './curriculum.js';
import {units,courses,questions,normalize,accessible,grade,courseStats,bridges,equalAnswer,splitWords} from './catalog-v4.js';
import {alphabet} from './alphabet.js';
import {readingBank} from './content-v4.js';
const $=s=>document.querySelector(s), app=$('#app'),modal=$('#modal');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
const local=createLocalStore();let extras;
const empty=()=>({completed:[],xp:0,days:{},mistakes:[]});
let lang=load('geo-lang','en'),view='learn',level='საწყისი',progress=local.active().progress,session=local.active().id==='guest'?null:{user:{id:local.active().id,nickname:local.active().nickname}},lesson=null,busy=false;
if(!courses[lang])lang='en';
const base=()=>getUiLanguage();
const sourceText=ka=>base()==='ka'?ka:(bridges[ka]?.[base()]||ka);
const sourceTitle=unit=>unit.titles?.[base()]||unit.title;
const sourceNote=unit=>unit.explanation?.[base()]||(base()==='ka'?unit.note:(noteBridge[unit.id]?.[base()]||unit.note));
const pronunciation=item=>base()==='ka'?`${item.hint} · მიახლოებითი გამოთქმა`:interfaceText('მოუსმინე ზუსტ გამოთქმას','Listen to the pronunciation','Послушай произношение');
const supportLabel=()=>interfaceText('ქართულად','with English support','с объяснениями на русском');
const hub=createLearningHub({show,speak,getCourse:()=>lang,getBase:base,getLearner:()=>local.active().id,onResult:recordResult,bankSize:key=>extras?.bankSize(key)||100,readPractice:()=>local.active().practice.hub?.[base()+'-'+lang],writePractice:state=>{local.active().practice.hub ||= {};local.active().practice.hub[base()+'-'+lang]=state;local.persist()},celebrate});
const today=()=>localDay();
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function save(){progress=local.saveProgress(progress);if(!local.persistent())toast(interfaceText('მეხსიერება სავსეა — ჩამოტვირთე შენი პროგრესი.','Storage is full — export your progress.','Память заполнена — экспортируй прогресс.'))}
function translationOf(item){return {ka:item.ka,en:item.en||bridges[item.ka]?.en||item.text,ru:item.ru||bridges[item.ka]?.ru||item.text}}
function recordResult(event){progress=local.result(event);const xp=$('#xp-total');if(xp)xp.textContent='✦ '+progress.xp+' XP'}
function calendarHtml(){return mondayWeek(today()).map((day,i)=>`<div class="day ${progress.activityDays?.[day]||progress.days[day]?'on':''} ${day===today()?'is-today':''}" title="${day}" data-date="${day}"><b>${progress.activityDays?.[day]||progress.days[day]?'✓':'·'}</b>${['ორ','სა','ოთ','ხუ','პა','შა','კვ'][i]}</div>`).join('')}
const mascot=`<svg class="mascot" viewBox="0 0 240 250" role="img" aria-label="ლინგო, მეგობრული მთის მეგზური"><ellipse cx="122" cy="232" rx="79" ry="10" fill="#d7cfee"/><path d="M45 153 Q13 127 28 110 Q46 107 66 132 M181 139 Q222 89 227 111 Q239 134 196 165" fill="#b4cf61" stroke="#73883b" stroke-width="3"/><path d="M78 202 L70 229 Q80 239 102 229 L106 203 M143 203 L145 230 Q164 241 179 230 L167 198" fill="#6a783d"/><path d="M44 180 Q45 125 91 42 Q106 15 125 47 L193 169 Q213 211 168 218 L78 218 Q36 216 44 180" fill="#c7e680" stroke="#abc76a" stroke-width="2"/><path d="M91 42 Q106 15 125 47 L147 87 L121 75 L106 89 L91 75 L70 88 Z" fill="#fffdf3"/><ellipse cx="119" cy="151" rx="54" ry="42" fill="#e0f3ad"/><ellipse cx="97" cy="139" rx="5" ry="8" fill="#33382c"/><ellipse cx="142" cy="139" rx="5" ry="8" fill="#33382c"/><circle cx="82" cy="155" r="9" fill="#e5a391" opacity=".7"/><circle cx="157" cy="155" r="9" fill="#e5a391" opacity=".7"/><path d="M109 157 Q120 172 132 157" fill="none" stroke="#33382c" stroke-width="4" stroke-linecap="round"/><path d="M57 183 Q105 168 168 184 L163 196 Q105 184 60 198Z" fill="#8b70cb"/><rect x="148" y="179" width="17" height="36" rx="4" fill="#8b70cb"/><path d="M188 44 L191 32 M180 36 L199 40 M30 72 L30 60 M24 66 L36 66" stroke="#ad95dc" stroke-width="3" stroke-linecap="round"/></svg>`;
function streak(){return currentStreak(progress,today())}
function header(){return `<div class="shell"><aside class="sidebar"><a class="brand" href="#">Geo<span>lingo</span><small>პატარა ნაბიჯი. დიდი სამყარო.</small></a><nav class="nav" aria-label="მთავარი მენიუ">${[['learn','⌂','ისწავლე'],['practice','✧','ივარჯიშე'],['words','▤','ლექსიკონი'],['leaders','♜','ლიდერები'],['resources','◎','რესურსები']].map(([v,i,t])=>`<button data-view="${v}" class="${view===v?'active':''}"><b>${i}</b>${t}</button>`).join('')}</nav><div class="side-bottom"><div class="ka-tag">შექმნილია ქართველებისთვის 🇬🇪<br>შენი ენა — შენი უპირატესობა.</div><button class="account" data-action="account"><span class="avatar">${session?'✓':base()==='ka'?'ნ':'G'}</span><span>${interfaceText('პროფილები','Profiles','Профили')}<small>${interfaceText('ინახება ამ მოწყობილობაზე','Saved on this device','Сохранено на устройстве')}</small></span></button></div></aside><main class="main"><header class="topbar"><div class="mobile-brand">Geo<span>lingo</span></div><select class="course-select" id="course" aria-label="სასწავლო ენა">${Object.entries(courses).map(([k,c])=>`<option value="${k}" ${lang===k?'selected':''}>${c.flag} ${c.name}</option>`).join('')}</select><div class="ui-controls"><select id="ui-language" aria-label="ინტერფეისის ენა" title="ინტერფეისის ენა"><option value="ka" ${getUiLanguage()==='ka'?'selected':''}>ქართული</option><option value="en" ${getUiLanguage()==='en'?'selected':''}>English</option><option value="ru" ${getUiLanguage()==='ru'?'selected':''}>Русский</option></select><button class="theme-toggle" data-action="theme" aria-label="${getTheme()==='dark'?'ნათელი თემა':'მუქი თემა'}" title="${getTheme()==='dark'?'ნათელი თემა':'მუქი თემა'}">${getTheme()==='dark'?'☀':'☾'}</button></div><div class="stats"><span title="სასწავლო დღეები">🔥 ${streak()}<small>სერია</small></span><span id="xp-total" title="გამოცდილების ქულები">✦ ${progress.xp}<small>XP</small></span><span class="mode badge">${interfaceText('● ადგილობრივი','● Local','● Локально')}</span><button class="text-button" data-action="account" aria-label="ანგარიში">☺</button></div></header><div id="content"></div></main></div>`}
function render(){app.innerHTML=header();const c=$('#content');if(view==='learn')c.innerHTML=learn();if(view==='practice')c.innerHTML=practice();if(view==='words')c.innerHTML=words();if(view==='leaders'){c.innerHTML=`<h1 class="view-title">პატარა ნაბიჯები, დიდი მიღწევები 🏆</h1><p class="sub">საერთო რეიტინგი • ქულები ორივე ენაში</p><div class="card" id="board">იტვირთება…</div>`;loadBoard()}if(view==='resources')c.innerHTML=resources();if(view==='learn')loadBoard(true)}
function learn(){const next=nextUnit();const current=units[lang].filter(u=>u.level===level);const daily=progress.days[today()]||0;return `<div class="dashboard"><section><div class="eyebrow">შენი ახალი თავგადასავალი</div><h1 class="greeting">გამარჯობა, ${session?'მეგობარო':'მომავალო პოლიგლოტო'}! <span>☀</span></h1><p class="sub">ახალი ენა იწყება ერთი პატარა ნაბიჯით. დღესაც ერთად გადავდგათ.</p><div class="hero"><div class="hero-content"><span class="pill">${courses[lang].flag} ${courses[lang].name} <span data-learning>${supportLabel()}</span></span><h2>მთელი სამყარო<br>ერთ გაკვეთილში.</h2><p>5 წუთი შენთვის. ახალი სიტყვები,<br>მეტი თავდაჯერება და პატარა გამარჯვება.</p><button class="primary" data-start="${next.index}">გააგრძელე სწავლა <span>↗</span></button></div><button class="mascot-button" data-action="mascot" aria-label="ლინგოს მიესალმე"><span class="mascot-bubble">ერთად გამოგვივა!</span>${mascot}</button></div><div class="section-head"><h2>შენი სასწავლო გზა</h2><small>${progress.completed.filter(x=>x.startsWith(lang+'-')).length} / ${units[lang].length} გაკვეთილი</small></div><div class="level-tabs" role="group" aria-label="დონეები">${levels.map(l=>`<button data-level="${l}" class="${level===l?'selected':''}">${l==='საწყისი'?'A0':l}</button>`).join('')}</div><div class="unit-banner"><div><small>${level==='საწყისი'?'ნულიდან ვიწყებთ':level+' • შემდეგი ნაბიჯი'}</small><h3>${{'საწყისი':'ყველაფერი იწყება გამარჯობით','A1':'ენა ყოველდღიურ ცხოვრებაში','A2':'მეტი ამბავი, მეტი შესაძლებლობა','B1':'საუბარი თავდაჯერებით','B2':'გამოხატე რთული აზრები'}[level]}</h3></div><span style="font-size:26px">${{'საწყისი':'🌱',A1:'🌿',A2:'🌳',B1:'⛰️',B2:'🚀'}[level]}</span></div><div class="path">${current.map(u=>{const done=progress.completed.includes(u.id),open=accessible(u.index,progress.completed,lang);return `<div style="--step:${u.index%24}" class="lesson-node ${done?'done':open?'available':''}"><button class="node-button" data-start="${u.index}" ${!open?'disabled':''} aria-label="${escape(sourceTitle(u))} ${done?'დასრულებულია':open?'დაწყება':'ჩაკეტილია'}">${done?'✓':open?'★':'⌑'}</button><div><h4>${sourceTitle(u)}</h4><p>${done?'შეგიძლია გაიმეორო':open?'მზად ხარ? დავიწყოთ!':'ჯერ წინა გაკვეთილი დაასრულე'}</p></div><span class="node-meta">${done?'✓':questions(u).length+' დავალება'}<br>${done?'დასრულებულია':'+40 XP'}</span></div>`}).join('')}</div><p class="footer-note">ყველა დონის პირველი გაკვეთილი ღიაა • შემდეგები იხსნება 80%-ით • მინიშნება დავალების XP-ს ანახევრებს.<br>საწყისი–B2 სასწავლო თემები. დასრულება B2 ცოდნის სერტიფიკატი არ არის.</p></section><aside class="right-rail"><div class="card"><div class="goal-top"><h3 style="margin:0">დღის პატარა მიზანი</h3><span>⚡</span></div><p class="sub">ცოტა ყოველდღე — და შენ შეძლებ.</p><div class="goal-top"><span>დღეს მიღებული XP</span><b>${daily} / 40</b></div><div class="bar"><div style="width:${Math.min(100,daily/40*100)}%"></div></div><div class="week">${calendarHtml()}</div></div>${extras?.questCard()||''}<div class="card challenge"><span class="challenge-icon">🎙️</span><h3 style="margin-top:12px">შენი ხმა მნიშვნელოვანია</h3><p>მოუსმინე, გაიმეორე და გაბედე.<br>იდეალური აქცენტი საჭირო არ არის.</p><button class="ghost" data-action="speak">ვივარჯიშოთ საუბარში →</button></div><div class="card leader-card"><div class="goal-top"><h3 style="margin:0">მეგობრული შეჯიბრი</h3><span>🏆</span></div><div id="mini-board"><p class="empty">იტვირთება…</p></div><button class="text-button" data-view="leaders">ყველა შედეგი →</button></div><p class="footer-note">ლინგო გეუბნება:<br>„შეცდომა სწავლის ნაწილია. სცადე კიდევ!“ ♡</p></aside></div>`}
function practice(){return `<h1 class="view-title">ივარჯიშე შენებურად ✧</h1><p class="sub">აქ არ არის წნეხი. მხოლოდ შენ და შენი პროგრესი.</p><div class="grid">${[['⚔','სიტყვების დუელი','სწორი თარგმანი და მართლწერა — შეეჯიბრე დროს.','duel'],['✨','ინტერაქტიული ამბები','შენი არჩევანი ცვლის თავგადასავალს.','stories'],['💎','შეცდომების საგანძური','შეასწორე შენახული სიტყვები და ფრაზები.','vault'],['🎯','დღიური მისიები','მიიღე ჯილდოები და შეინარჩუნე სერია.','quests'],['💬','ყოველდღიური საუბრები','რესტორანი, აეროპორტი, სასტუმრო, მაღაზია და ქალაქი.','conversations'],['📚','ტექსტები და დიალოგები','იკითხე და მოუსმინე ამბებს, შეამოწმე გაგება და ნახე ქართული თარგმანი.','reading'],['🔤','ანბანი და ბგერები','დაიწყე ნულიდან: ასოები, სახელები და ქართული მინიშნებები.','alphabet'],['🔊','მოსმენა','A0–B2 · 8 მოდული თითო დონეზე · ადგილობრივი ხმები.','listen'],['🎙️','საუბარი','მოისმინე ნიმუში, ჩაიწერე ხმა და შეადარე.','speak'],['📖','გრამატიკა','A0–B2 · წესები, მაგალითები და მრავალფეროვანი პრაქტიკა.','grammar']].map(([s,t,d,a])=>`<div class="card practice-card"><span class="symbol">${s}</span><h2>${t}</h2><p>${d}</p><button class="ghost" data-action="${a}">დაწყება →</button></div>`).join('')}</div>`}
function words(q=''){const items=units[lang].filter(u=>accessible(u.index,progress.completed,lang)).flatMap(u=>u.items);return `<h1 class="view-title">შენი სიტყვების კოლექცია ▤</h1><p class="sub">${interfaceText('გახსნილი გაკვეთილების სიტყვები და ფრაზები • გამოთქმა ქართული მინიშნებით','Words and phrases from unlocked lessons • Listen to the pronunciation','Слова и фразы открытых уроков • Слушай произношение')}</p><input id="search" class="search" placeholder="მოძებნე სიტყვა…" value="${escape(q)}" aria-label="სიტყვის ძებნა"><div class="words">${items.filter(i=>(i.text+' '+sourceText(i.ka)).toLowerCase().includes(q.toLowerCase())).map(i=>`<div class="word-card"><button data-audio="${escape(i.text)}" aria-label="მოსმენა">▶</button><strong>${escape(i.text)}</strong><span>${escape(sourceText(i.ka))}</span><small>${escape(pronunciation(i))}</small></div>`).join('')||'<p>სიტყვა ვერ მოიძებნა.</p>'}</div>`}
function resources(){return `<h1 class="view-title">${interfaceText('Geolingo · ადგილობრივი სასწავლო ბიბლიოთეკა','Geolingo · Local learning library','Geolingo · Локальная учебная библиотека')}</h1><div class="resource-totals"><div><b>${courseStats.lessons}</b><span>${interfaceText('გაკვეთილი','lessons','уроков')}</span></div><div><b>10,000</b><span>${interfaceText('ტექსტის და დიალოგის სავარჯიშო','reading and dialogue exercises','заданий к текстам и диалогам')}</span></div><div><b>8</b><span>${interfaceText('ინტერაქტიული ამბავი','interactive stories','интерактивных историй')}</span></div><div><b>4</b><span>${interfaceText('სასწავლო ენა','learning languages','изучаемых языка')}</span></div></div><p class="note">${interfaceText('ყველა სასწავლო მასალა ადგილობრივ ფაილებშია. გარე API, გამოწერა და ხელოვნურად შექმნილი რეიტინგი არ გამოიყენება.','All learning materials are local files. No external API, subscription or fabricated leaderboard.','Все учебные материалы находятся в локальных файлах. Без внешних API, подписки и вымышленного рейтинга.')}</p><p class="sub">${interfaceText('აუდიო იყენებს მხოლოდ მოწყობილობაზე დაყენებულ ადგილობრივ ხმებს. სხვა მოწყობილობაზე პროგრესის გადასატანად ჩამოტვირთე პროფილის ფაილი.','Audio uses only installed offline voices. Export your profile file to transfer progress to another device.','Аудио использует только установленные локальные голоса. Экспортируй профиль для переноса прогресса.')}</p><button class="primary" data-action="export">ჩამოტვირთე ჩემი პროგრესი</button><p class="footer-note">Geolingo 4.0 · ${interfaceText('A0–B2 სასწავლო თემები; დასრულება CEFR სერტიფიკატი არ არის.','A0–B2 practice topics; completion is not CEFR certification.','Учебные темы A0–B2; завершение не является сертификатом CEFR.')}</p>`}

async function loadBoard(mini=false){const target=$(mini?'#mini-board':'#board');if(!target)return;const rows=local.leaderboard();target.innerHTML=`<p class="hint">${interfaceText('ამ მოწყობილობის რეიტინგი · კვირა იწყება ორშაბათს','This device’s leaderboard · Week starts Monday','Рейтинг этого устройства · Неделя начинается в понедельник')}</p>`+rows.slice(0,mini?3:50).map((r,i)=>`<div class="row ${r.id===local.active().id?'my-rank':''}"><span class="rank">${i+1}</span><span class="avatar">${i===0?'🏅':'✦'}</span><strong data-learning>${escape(r.nickname)}</strong><span class="points">${r.weekly} XP<small>${r.streak} 🔥</small></span></div>`).join('')+`<p class="hint">${interfaceText('რეალური ადგილობრივი პროფილები; სხვა მოწყობილობების საერთო რეიტინგი სერვერის გარეშე არ სინქრონდება.','Real local profiles; cross-device rankings are not synchronized without a server.','Реальные локальные профили; без сервера рейтинг между устройствами не синхронизируется.')}</p>`}

function show(html,kind='general'){stopRecording();extras?.cancelTimers();modal.dataset.kind=kind;modal.classList.remove('answer-right','answer-wrong');modal.innerHTML=`<button class="modal-outside-close" data-action="close" aria-label="ფანჯრის დახურვა">×</button><div class="modal-pad">${html}</div>`;modal.querySelectorAll(".modal-pad .close").forEach(b=>b.remove());if(!modal.open)modal.showModal()}
let audioTicket=0;
function availableVoices(){return rankVoices(window.speechSynthesis?.getVoices().filter(v=>v.localService===true)||[],courses[lang].locale)}
function voiceOptions(){const voices=availableVoices();return `<option value="">${getUiLanguage()==='en'?'Automatic · best available':'ავტომატური · საუკეთესო ხელმისაწვდომი'}</option>`+voices.map(v=>`<option value="${escape(v.voiceURI)}" ${load('geo-voice-'+lang,'')===v.voiceURI?'selected':''}>${escape(v.name)} (${escape(v.lang)})</option>`).join('')}
function updateVoiceOptions(){const select=$('#voice-select');if(select)select.innerHTML=voiceOptions()}
window.speechSynthesis?.addEventListener?.('voiceschanged',updateVoiceOptions);
async function speak(text,slow=false){
 if(!('speechSynthesis'in window)){toast('ამ ბრაუზერში ხმა მიუწვდომელია. გამოიყენე წერითი დავალება.');return}
 stopRecording();const ticket=++audioTicket;speechSynthesis.cancel();
 if(!speechSynthesis.getVoices().length)await new Promise(resolve=>{const timer=setTimeout(done,900);function done(){clearTimeout(timer);speechSynthesis.removeEventListener?.('voiceschanged',done);resolve()}speechSynthesis.addEventListener?.('voiceschanged',done,{once:true})});
 if(ticket!==audioTicket)return;
 const u=new SpeechSynthesisUtterance(text),voices=availableVoices();u.lang=courses[lang].locale;u.rate=slow?.72:1;u.pitch=1;u.volume=1;u.voice=voices.find(v=>v.voiceURI===load('geo-voice-'+lang,''))||voices[0]||null;if(!u.voice){toast(interfaceText('ამ ენაზე ადგილობრივი ხმა არ არის დაყენებული. აუდიო არ გაიგზავნება გარე სერვისზე.','No offline voice is installed for this language. No text is sent to an external service.','Для этого языка нет локального голоса. Текст не отправляется внешнему сервису.'));return}
 u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast(getUiLanguage()==='en'?'Audio unavailable. Try another voice.':'ხმა მიუწვდომელია. სხვა ხმა აირჩიე.')};speechSynthesis.speak(u);
}
function shuffled(a){return [...a].sort(()=>Math.random()-.5)}
function nextUnit(){const us=units[lang].filter(u=>u.level===level);return us.find(u=>!progress.completed.includes(u.id)&&accessible(u.index,progress.completed,lang))||us[0]||units[lang][0]}
function start(index,mode){
 const unit=units[lang][index];if(!unit||!accessible(index,progress.completed,lang))return toast('ამ დონეზე ჯერ წინა გაკვეთილი დაასრულე.');
 level=unit.level;lesson={unit,qs:questions(unit).filter(q=>!mode||q.type===mode),i:0,score:0,answers:[],hints:[],selected:'',checked:false,practice:!!mode,bank:[],chosen:[]};
 show(`<div class="modal-top"><button class="close" data-action="close" aria-label="დახურვა">×</button><span class="badge">${unit.level==='საწყისი'?'A0':unit.level} • ${sourceTitle(unit)}</span></div><div class="eyebrow">გაიგე • მოუსმინე • ივარჯიშე</div><h2 class="lesson-title">${sourceTitle(unit)}</h2><div class="note" data-learning>${escape(sourceNote(unit))}</div><h3>ჯერ გავეცნოთ სიტყვებსა და ფრაზებს</h3><div class="study-phrases">${unit.items.map(i=>`<div class="study-phrase"><button class="text-button" data-audio="${escape(i.text)}" aria-label="${escape(i.text)} მოსმენა">🔊</button><strong>${escape(i.text)}</strong><span>${escape(sourceText(i.ka))}</span><small>${escape(pronunciation(i))}</small></div>`).join('')}</div><p class="hint">${lesson.practice?'სავარჯიშო რეჟიმი — XP და ახალი გაკვეთილი არ გაიცემა.':`${lesson.qs.length} დავალება • გასავლელად საჭიროა 80% • მაქსიმუმ 40 XP პირველად გავლისას`}</p><p class="hint">💡 მინიშნების გამოყენება მხოლოდ მიმდინარე დავალების შესაძლო ქულას ანახევრებს. სხვა დავალებების ქულა უცვლელია.</p><div class="lesson-actions"><span class="hint">დახურვა: ×, Esc ან ფანჯრის გარეთ დაწკაპუნება.</span><button class="primary" data-action="begin">დავიწყოთ →</button></div>`)
}
function drawQuestion(){
 const q=lesson.qs[lesson.i];lesson.selected='';lesson.checked=false;lesson.chosen=[];lesson.bank=shuffled(splitWords(q.item.text,lang)).map((text,i)=>({text,i}));
 const labels={meaning:'რას ნიშნავს ეს ფრაზა?',listen:'მოუსმინე და ჩაწერე გაგონილი',write:'თარგმნე სასწავლო ენაზე',order:'დაალაგე სიტყვები სწორად'};
 let html=`<div class="modal-top"><button class="close" data-action="close" aria-label="დახურვა">×</button><div class="bar"><div style="width:${lesson.i/lesson.qs.length*100}%"></div></div><span class="hint">${lesson.i+1}/${lesson.qs.length}</span></div><span class="eyebrow">${sourceTitle(lesson.unit)}</span><div class="exercise-heading"><div class="mini-guide" aria-hidden="true">${mascot}</div><h2 class="lesson-title">${labels[q.type]}</h2></div>`;
 if(q.type==='meaning')html+=`<div class="prompt">${escape(q.item.text)} <button class="text-button" data-audio="${escape(q.item.text)}" aria-label="მოსმენა">🔊</button></div><div class="choices">${shuffled(lesson.unit.items.map(i=>i.ka).filter((x,i,a)=>a.findIndex(v=>sourceText(v)===sourceText(x))===i)).map(x=>`<button class="choice" data-choice="${escape(x)}">${escape(sourceText(x))}</button>`).join('')}</div>`;
 if(q.type==='listen')html+=`<div class="listen-prompt"><button class="audio" data-audio="${escape(q.item.text)}" aria-label="ფრაზის მოსმენა">▶</button><br><button class="text-button" data-slow="${escape(q.item.text)}">🐢 ნელა მოსმენა</button><br><button class="text-button" data-action="hint">ხმა მიუწვდომელია? ნახე ტექსტი · ½ XP</button></div><input class="answer-input" id="answer" autocomplete="off" placeholder="ჩაწერე გაგონილი ფრაზა…" aria-label="პასუხი">`;
 if(q.type==='write')html+=`<div class="prompt">${escape(sourceText(q.item.ka))}</div><input class="answer-input" id="answer" autocomplete="off" placeholder="${{en:'Write in English…',ru:'Напишите по-русски…',zh:'用中文写…',es:'Escribe en español…'}[lang]}" aria-label="თარგმანი"><p class="hint">გამოიყენე გაკვეთილის ფრაზა. პუნქტუაცია და დიდი ასოები არ ფასდება.</p>`;
 if(q.type==='order')html+=`<div class="prompt">${escape(sourceText(q.item.ka))}</div><div class="answer-zone word-bank" id="chosen"></div><div class="word-bank" id="bank">${lesson.bank.map(w=>`<button data-word="${w.i}">${escape(w.text)}</button>`).join('')}</div><p class="hint">სიტყვის დასაბრუნებლად მას ხელახლა დააჭირე.</p>`;
 show(html+`<div class="clue-bar"><button class="clue-button" data-action="hint">💡 მინიშნება <small>მხოლოდ ამ დავალების XP ×½</small></button><span id="task-xp">${(40/lesson.qs.length).toFixed(2)} XP</span></div><div id="clue-content" aria-live="polite"></div><div id="feedback" role="status" aria-live="polite"></div><div class="lesson-actions"><span class="hint">${courses[lang].flag} ${courses[lang].name} • <span data-learning>${supportLabel()}</span></span><button class="primary" data-action="check">შეამოწმე</button></div>`,'exercise');if(window.matchMedia?.('(min-width:621px)').matches)$('#answer')?.focus();
}
function revealHint(){
 if(!lesson||lesson.checked||lesson.hints[lesson.i])return;
 const q=lesson.qs[lesson.i];lesson.hints[lesson.i]=true;
 $('#clue-content').innerHTML=`<div class="clue-content"><strong>მინიშნება</strong><p>${escape(q.type==='meaning'?sourceText(q.answer):q.answer)}</p><span>${escape(sourceText(q.item.ka))}</span>${base()==='ka'?`<small>გამოთქმა: ${q.item.hint}</small>`:''}<small>ამ დავალების ქულა განახევრებულია; გავლის 80%-იან ზღვარზე ეს გავლენას არ ახდენს.</small></div>`;
 $('#task-xp').textContent=(20/lesson.qs.length).toFixed(2)+' XP';
 modal.querySelectorAll('[data-action="hint"]').forEach(b=>{b.disabled=true});
}
function check(){
 if(!lesson||lesson.checked)return;const q=lesson.qs[lesson.i];
 const answer=q.type==='meaning'?lesson.selected:q.type==='order'?lesson.chosen.map(i=>lesson.bank.find(w=>w.i===i).text).join(lang==='zh'?'':' '):$('#answer').value;
 if(!answer.trim())return toast('ჯერ უპასუხე დავალებას.');const canonicalAnswer=q.type==='meaning'&&sourceText(answer)===sourceText(q.answer)?q.answer:answer;lesson.answers.push(canonicalAnswer);lesson.hints[lesson.i]=!!lesson.hints[lesson.i];
 const correct=equalAnswer(canonicalAnswer,q.answer,lang);recordResult({correct,target:lang,expected:q.item.text,answer,translation:translationOf(q.item),origin:'lesson'});lesson.score+=correct?1:0;lesson.checked=true;modal.classList.add(correct?'answer-right':'answer-wrong');
 if(!correct&&!progress.mistakes.includes(q.item.id)){progress.mistakes.push(q.item.id);save()}
 if(correct){progress.mistakes=progress.mistakes.filter(x=>x!==q.item.id);save()}
 $('#feedback').innerHTML=`<div class="feedback ${correct?'':'bad'}"><strong>${correct?'ყოჩაღ! სწორია. ✦':'კარგი ცდა! ერთად გავიმეოროთ.'}</strong>${correct?`<br>ამ დავალების წილი: ${((lesson.hints[lesson.i]?20:40)/lesson.qs.length).toFixed(2)} XP`:`<br>სწორი პასუხი: ${escape(q.type==='meaning'?sourceText(q.answer):q.answer)}<br>${escape(sourceText(q.item.ka))}<br>${base()==='ka'?`<span class="hint">მიახლოებითი გამოთქმა: ${q.item.hint}</span>`:''}`}</div>`;
 modal.querySelectorAll('.choice,.word-bank button,input,[data-action="hint"]').forEach(e=>e.disabled=true);const b=modal.querySelector('[data-action="check"]');b.dataset.action='next';b.textContent=lesson.i===lesson.qs.length-1?'შედეგები →':'შემდეგი →';
}
async function finish(){if(busy)return;busy=true;try{const result=grade(lesson.qs,lesson.answers,lesson.hints);let award=0;if(!lesson.practice&&result.passed&&!progress.completed.includes(lesson.unit.id)){progress.completed.push(lesson.unit.id);progress.xp+=result.award;progress.days[today()]=(progress.days[today()]||0)+result.award;award=result.award;save()}show(`<div class="result"><span class="medal">${result.passed?'🏆':'🌱'}</span><h2>${result.passed?'ერთი ნაბიჯით წინ!':'სწავლა გრძელდება!'}</h2><div class="result-stats"><span><b>${Math.round(result.score/lesson.qs.length*100)}%</b>${result.score}/${lesson.qs.length}</span><span><b>+${award}</b>XP</span></div><p class="hint">${interfaceText('პროგრესი ინახება ამ მოწყობილობაზე.','Progress is saved on this device.','Прогресс сохранён на этом устройстве.')}</p><button class="primary" data-action="close">გზაზე დაბრუნება →</button></div>`,'result');render();if(result.passed)celebrate()}finally{busy=false}}

let readingState=null;
function readingLibrary(){show(`<h2>ტექსტები და დიალოგები 📚</h2><p class="sub">${interfaceText('თითო ტექსტზე 100 მრავალფეროვანი სავარჯიშო.','100 varied exercises for every text.','100 разнообразных заданий к каждому тексту.')}</p>${levels.map(l=>`<h3>${l==='საწყისი'?'A0':l}</h3><div class="reading-list">${(readingBank[lang]||[]).filter(s=>s.level===l).map(s=>`<button class="reading-link" data-read="${s.id}"><span>${typeof s.title==='object'?s.title[base()]:s.title}</span><small>${extras.bankSize(s.id)} →</small></button>`).join('')}</div>`).join('')}`,'library')}
function openReading(id){const story=readingBank[lang].find(s=>s.id===id);if(!story)return;const title=typeof story.title==='object'?story.title[base()]:story.title,translation=base()==='ka'?story.ka:(story.translation?.[base()]||readingSupport[story.id]?.[base()]?.translation||story.ka);show(`<h2>${title}</h2><div class="reading-tools"><button class="ghost" data-audio="${escape(story.passage)}">🔊 ${interfaceText('მოსმენა','Listen','Слушать')}</button><button class="ghost" data-slow="${escape(story.passage)}">🐢</button></div><p class="reading-passage" data-learning>${escape(story.passage)}</p><details class="translation"><summary>${interfaceText('თარგმანი','Translation','Перевод')}</summary><p data-learning>${escape(translation)}</p></details><button class="primary bank-launch" data-v4="bank-library" data-bank="${story.id}">${extras.bankSize(story.id)} ${interfaceText('სავარჯიშო →','exercises →','заданий →')}</button>`,'article')}

function auth(){show(`<h2>${interfaceText('ადგილობრივი პროფილები','Local profiles','Локальные профили')}</h2><p class="sub">${interfaceText('ელფოსტისა და სერვერის გარეშე. მონაცემები ამ ბრაუზერში რჩება; პროფილის ფაილი შეგიძლია სხვა მოწყობილობაზე გადაიტანო.','No email or server. Data stays in this browser; export a profile to transfer it to another device.','Без почты и сервера. Данные остаются в браузере; профиль можно перенести файлом на другое устройство.')}</p><div class="reading-list">${local.profiles().map(p=>`<button class="reading-link" data-profile="${escape(p.id)}"><span data-learning>${escape(p.nickname)}</span><b>${p.id===local.active().id?'✓':p.progress.xp+' XP'}</b></button>`).join('')}</div><form id="local-profile-form" class="auth-form"><label>${interfaceText('ახალი პროფილის სახელი','New profile name','Имя нового профиля')}<input name="nickname" required minlength="2" maxlength="24" autocomplete="nickname"></label><button class="primary">${interfaceText('შექმენი პროფილი','Create profile','Создать профиль')}</button></form><p id="profile-error" role="status"></p><div class="auth-links"><button data-action="export">${interfaceText('პროფილის ჩამოტვირთვა','Export profile','Экспорт профиля')}</button><label class="ghost import-label">${interfaceText('ფაილიდან შემოტანა','Import file','Импорт файла')}<input id="profile-import" type="file" accept="application/json,.json"></label></div>`,'general')}
function refreshProfile(){progress=local.active().progress;session=local.active().id==='guest'?null:{user:{id:local.active().id,nickname:local.active().nickname}};render()}
document.addEventListener('submit',e=>{if(e.target.id!=='local-profile-form')return;e.preventDefault();try{local.createProfile(e.target.elements.nickname.value);refreshProfile();modal.close()}catch(error){$('#profile-error').textContent=error.message}});

let recorder,recordStream,recordingUrl,recordingTimer;
let recordingGeneration=0;
function showAlphabet(){const rows=alphabet[lang]||extraAlphabet[lang],note=extraAlphabetNotes[lang]?.[base()]||alphabetNotes[lang]?.[base()]||interfaceText('მოუსმინე ასოებს და სიტყვებს. გამოთქმის მინიშნებები მიახლოებითია.','Listen to letters and words. Pronunciation hints are approximate.','Слушай буквы и слова. Подсказки произношения приблизительные.');show(`<h2>${lang==='zh'?'Pinyin':interfaceText('ანბანი და ბგერები','Alphabet and sounds','Алфавит и звуки')} · ${courses[lang].flag}</h2><p class="note" data-learning>${escape(note)}</p><div class="words">${rows.map(([letter,hint],index)=>`<div class="word-card"><button data-audio="${escape(letter)}">▶</button><strong data-learning>${escape(letter)}</strong><small data-learning>${escape(base()==='ka'?hint:alphabetSupport[lang]?.[index]||hint)}</small></div>`).join('')}</div>`,'library')}

let speakingIndex=0;
function stopRecording(){audioTicket++;recordingGeneration++;clearTimeout(recordingTimer);modal.classList.remove('recording');if(recorder?.state==='recording')recorder.stop();recordStream?.getTracks().forEach(t=>t.stop());if(recordingUrl){URL.revokeObjectURL(recordingUrl);recordingUrl=null}window.speechSynthesis?.cancel()}
function speaking(){const u=nextUnit();speakingIndex%=u.items.length;const x=u.items[speakingIndex];show(`<div class="speaking-stage"><div class="eyebrow" data-learning>პატარა ნაბიჯი დიდი მიზნისკენ</div><h2>${interfaceText('მოუსმინე და გაიმეორე','Listen and repeat','Послушай и повтори')}</h2><div class="speech-bubble" data-learning>${escape(x.text)} <button class="text-button" data-audio="${escape(x.text)}">🔊</button></div><p data-learning>${escape(sourceText(x.ka))}</p><div class="speaking-character" aria-hidden="true">${characterSvg('fox')}</div><div class="voice-wave" aria-hidden="true">${'<i></i>'.repeat(7)}</div><button class="speech-mic big-mic" data-record="${speakingIndex}" aria-label="${interfaceText('ხმის ჩაწერა','Record voice','Записать голос')}">🎙</button><p class="speaking-motto" data-learning>პატარა ნაბიჯი დიდი მიზნისკენ</p><div id="record-${speakingIndex}"></div><div class="speech-controls"><button class="ghost" data-slow="${escape(x.text)}">🐢 ${interfaceText('ნელა','Slowly','Медленно')}</button><button class="ghost" data-action="speech-next">${interfaceText('შემდეგი ფრაზა','Next phrase','Следующая фраза')} →</button></div><button id="speech-self-check" class="ghost" data-action="speech-self-check" disabled>${interfaceText('ჩანაწერი ნიმუშს შევადარე','I compared my recording with the sample','Я сравнил запись с образцом')}</button><details class="voice-settings"><summary>${interfaceText('ადგილობრივი ხმის არჩევა','Choose an offline voice','Выбрать локальный голос')}</summary><select id="voice-select">${voiceOptions()}</select></details><p class="hint">${interfaceText('ხმა რჩება ამ მოწყობილობაზე. მოუსმინე ორივე ჩანაწერს და თავად შეადარე. ავტომატური შეფასება არ ხდება.','Audio stays on this device. Listen and compare the recordings yourself. There is no automatic accuracy score.','Аудио остаётся на устройстве. Сравни записи самостоятельно. Автоматической оценки точности нет.')}</p></div>`,'speaking')}

async function record(i){
 if(recorder?.state==='recording'){recorder.stop();return}
 audioTicket++;window.speechSynthesis?.cancel();
 const ticket=++recordingGeneration;let stream;
 try{
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('ჩაწერა ამ ბრაუზერში მიუწვდომელია.');
  stream=await navigator.mediaDevices.getUserMedia({audio:true});
  if(ticket!==recordingGeneration||!modal.open){stream.getTracks().forEach(t=>t.stop());return}
  const active=new MediaRecorder(stream);recordStream=stream;recorder=active;const chunks=[];
  active.ondataavailable=e=>chunks.push(e.data);
  active.onstop=()=>{
   stream.getTracks().forEach(t=>t.stop());clearTimeout(recordingTimer);modal.classList.remove('recording');
   if(ticket!==recordingGeneration||!modal.open)return;
   if(recordingUrl)URL.revokeObjectURL(recordingUrl);
   recordingUrl=URL.createObjectURL(new Blob(chunks,{type:active.mimeType}));
   const t=$('#record-'+i);if(t){t.innerHTML='<audio controls src="'+recordingUrl+'"></audio>';$('#speech-self-check')?.removeAttribute('disabled');const b=modal.querySelector('[data-record="'+i+'"]');if(b)b.textContent='🎙'}
  };
  active.start();modal.classList.add('recording');const b=modal.querySelector('[data-record="'+i+'"]');if(b)b.textContent='■';
  recordingTimer=setTimeout(()=>{if(active.state==='recording')active.stop()},20000);
 }catch(e){stream?.getTracks().forEach(t=>t.stop());if(ticket===recordingGeneration)toast('მიკროფონი მიუწვდომელია: '+e.message)}
}

function review(){extras.vault()}

document.addEventListener('click',async e=>{const b=e.target.closest('button,a.brand,summary[data-v3]');if(!b)return;try{if(extras?.click(b)||hub.click(b))return;if(b.dataset.profile){local.switchProfile(b.dataset.profile);refreshProfile();modal.close();return}if(b.matches('a.brand')){e.preventDefault();view='learn';render()}if(b.dataset.view){view=b.dataset.view;render()}if(b.dataset.level){level=b.dataset.level;render()}if(b.dataset.start!==undefined)start(Number(b.dataset.start));if(b.dataset.audio)speak(b.dataset.audio);if(b.dataset.slow)speak(b.dataset.slow,true);if(b.dataset.read)openReading(b.dataset.read);if(b.dataset.record!==undefined)await record(Number(b.dataset.record));if(b.dataset.choice){lesson.selected=b.dataset.choice;modal.querySelectorAll('.choice').forEach(x=>x.classList.toggle('chosen',x===b))}if(b.dataset.word!==undefined&&!lesson.checked){const i=Number(b.dataset.word);if(lesson.chosen.includes(i))lesson.chosen=lesson.chosen.filter(x=>x!==i);else lesson.chosen.push(i);$('#chosen').innerHTML=lesson.chosen.map(i=>`<button data-word="${i}">${escape(lesson.bank.find(w=>w.i===i).text)}</button>`).join('');$('#bank').innerHTML=lesson.bank.filter(w=>!lesson.chosen.includes(w.i)).map(w=>`<button data-word="${w.i}">${escape(w.text)}</button>`).join('')}
 const a=b.dataset.action;if(a==='theme'){toggleTheme();render()}if(a==='mascot'){b.classList.remove('cheer');void b.offsetWidth;b.classList.add('cheer');toast(getUiLanguage()==='en'?'You can do this! One step at a time.':'შენ შეძლებ! ნაბიჯ-ნაბიჯ, ერთად.')}if(a==='close')modal.close();if(a==='begin')drawQuestion();if(a==='check')check();if(a==='next'){lesson.i++;if(lesson.i>=lesson.qs.length)await finish();else drawQuestion()}if(a==='retry-save')await finish();if(a==='account')auth();if(a==='alphabet')showAlphabet();if(a==='reading')readingLibrary();if(a==='hint')revealHint();if(a==='speak'){speakingIndex=0;speaking()}if(a==='speech-next'){speakingIndex++;speaking()}if(a==='speech-self-check'){const item=nextUnit().items[speakingIndex];local.active().progress.activityDays[today()]=true;local.award(1,'speaking:'+today()+':'+item.id);save();b.disabled=true;toast(interfaceText('კარგი პრაქტიკაა!','Good practice!','Хорошая практика!'))}if(['duel','stories','vault','quests'].includes(a))extras.click({dataset:{v4:a}});if(a==='review')review();if(a==='review-test'){const u=units[lang].find(u=>u.items.some(i=>progress.mistakes.includes(i.id)))||units[lang].find(u=>!progress.completed.includes(u.id))||units[lang][0];start(u.index,'write')}if(a==='listen')hub.library('listen');if(a==='conversations')hub.conversations();if(a==='grammar')hub.library('grammar');if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(local.exportProfile(),null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='geolingo-progress.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}catch(err){toast(err.message)}});
document.addEventListener('change',async e=>{if(e.target.id==='profile-import'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw Error('File too large.');local.importProfile(JSON.parse(await file.text()));refreshProfile();modal.close()}catch(error){$('#profile-error').textContent=error.message}return}if(e.target.id==='voice-select'){localStorage.setItem('geo-voice-'+lang,JSON.stringify(e.target.value))}if(e.target.id==='ui-language'){setUiLanguage(e.target.value);render()}if(e.target.id==='course'){lang=e.target.value;localStorage.setItem('geo-lang',JSON.stringify(lang));level=units[lang].find(u=>!progress.completed.includes(u.id))?.level||'საწყისი';render()}});
document.addEventListener('input',e=>{hub.input(e);if(e.target.id==='search'){const pos=e.target.selectionStart;$('#content').innerHTML=words(e.target.value);$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{extras?.keydown(e);hub.keydown(e);if(e.key==='Enter'&&modal.open&&$('#answer')===document.activeElement){e.preventDefault();if(!lesson.checked)check();else modal.querySelector('[data-action="next"]')?.click()}});
// Import previously cached mistakes without fabricating activity or points.
for(const id of progress.mistakes){for(const [target,us]of Object.entries(units)){const item=us.flatMap(u=>u.items).find(i=>i.id===id);if(item){const key=target+'|'+item.text.normalize('NFKC').toLowerCase();local.active().vault[key] ||= {target,expected:item.text,answer:'',translation:translationOf(item),origin:'lesson',count:1,last:today(),resolved:false};break}}}local.persist();
extras=createOfflineActivities({show,speak,store:local,getCourse:()=>lang,getBase:base,getItems:()=>units[lang].filter(u=>u.level===level).flatMap(u=>u.items.map(item=>({...item,translation:translationOf(item)}))),onUpdate:()=>{progress=local.active().progress},celebrate,escape});
startLocalization();modal.addEventListener('close',()=>{stopRecording();extras.dismiss();render()});render();



let backdropPointer=false;
modal.addEventListener('pointerdown',e=>{const r=modal.getBoundingClientRect();backdropPointer=e.target===modal&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)});
modal.addEventListener('click',e=>{if(e.target===modal&&backdropPointer){backdropPointer=false;modal.close()}});
